contracts/Pengupunk.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.24;

import {ERC721} from "@openzeppelin/contracts/token/ERC721/ERC721.sol";
import {ERC2981} from "@openzeppelin/contracts/token/common/ERC2981.sol";
import {Strings} from "@openzeppelin/contracts/utils/Strings.sol";
import {Base64} from "@openzeppelin/contracts/utils/Base64.sol";

interface IAgentRegistry {
    function balanceOf(address owner) external view returns (uint256);
}

/// @title Pengupunk — agent-gated collectible on BNB Chain
/// @notice Tidak ada owner, pause, withdraw, atau setPrice. Semua aturan dikunci saat deploy.
/// Harga: keping #1 = 0.001 BNB, #2 = 0.0005 BNB, #3 gratis (kuota terbatas), maks 3 per wallet.
/// Dana langsung diteruskan ke treasury pada transaksi mint.
contract Pengupunk is ERC721, ERC2981 {
    using Strings for uint256;

    uint256 public constant MAX_SUPPLY = 2222;
    uint256 public constant MAX_PER_WALLET = 3;
    uint256 public constant PRICE_FIRST = 0.001 ether;
    uint256 public constant PRICE_SECOND = 0.0005 ether;
    uint256 public constant FREE_QUOTA = 223;
    uint96 public constant ROYALTY_BPS = 250; // 2.5%

    IAgentRegistry public immutable agentRegistry;
    address payable public immutable treasury;

    uint256 public immutable revealBlock;
    bytes32 public immutable provenanceCommit;

    uint256 public totalMinted;
    uint256 public freeGranted;
    bytes32 public revealSecret;
    uint256 public seed;

    mapping(address => uint256) public mintedBy;

    event Minted(address indexed to, uint256 firstId, uint256 qty, uint256 paid, bool thirdFree);
    event Revealed(bytes32 secret, uint256 seed);

    constructor(
        address registry_,
        address payable treasury_,
        uint256 revealDelayBlocks_,
        bytes32 provenanceCommit_
    ) ERC721("Pengupunk", "PUNK") {
        require(registry_ != address(0) && treasury_ != address(0), "addr");
        require(provenanceCommit_ != bytes32(0), "commit");
        require(revealDelayBlocks_ > 0, "delay");
        agentRegistry = IAgentRegistry(registry_);
        treasury = treasury_;
        revealBlock = block.number + revealDelayBlocks_;
        provenanceCommit = provenanceCommit_;
        _setDefaultRoyalty(treasury_, ROYALTY_BPS);
    }

    // ---------------------------------------------------------------- mint

    /// @notice Harga yang harus dibayar wallet ini untuk `qty` keping berikutnya.
    function priceFor(address wallet, uint256 qty) public view returns (uint256) {
        uint256 already = mintedBy[wallet];
        uint256 freeLeft = FREE_QUOTA - freeGranted;
        uint256 cost;
        for (uint256 i = 0; i < qty; i++) {
            uint256 slot = already + i + 1; // keping ke-1, ke-2, ke-3
            if (slot == 1) cost += PRICE_FIRST;
            else if (slot == 2) cost += PRICE_SECOND;
            else if (slot == 3) {
                if (freeLeft > 0) freeLeft -= 1; // gratis, kurangi kuota
                else cost += PRICE_SECOND;
            } else {
                revert("max per wallet");
            }
        }
        return cost;
    }

    function mint(uint256 qty) external payable {
        require(qty >= 1 && qty <= MAX_PER_WALLET, "qty");
        require(mintedBy[msg.sender] + qty <= MAX_PER_WALLET, "max per wallet");
        require(totalMinted + qty <= MAX_SUPPLY, "sold out");
        require(agentRegistry.balanceOf(msg.sender) > 0, "not agent");

        uint256 cost = priceFor(msg.sender, qty);
        require(msg.value >= cost, "underpaid");

        uint256 already = mintedBy[msg.sender];
        mintedBy[msg.sender] = already + qty;

        // hitung berapa keping gratis yang dipakai
        bool thirdFree;
        uint256 freeLeft = FREE_QUOTA - freeGranted;
        for (uint256 i = 0; i < qty; i++) {
            if (already + i + 1 == 3 && freeLeft > 0) {
                freeLeft -= 1;
                freeGranted += 1;
                thirdFree = true;
            }
        }

        uint256 startId = totalMinted + 1;
        totalMinted += qty;
        for (uint256 i = 0; i < qty; i++) {
            _safeMint(msg.sender, startId + i);
        }

        if (cost > 0) {
            (bool ok, ) = treasury.call{value: cost}("");
            require(ok, "treasury transfer");
        }
        if (msg.value > cost) {
            (bool back, ) = msg.sender.call{value: msg.value - cost}("");
            require(back, "refund");
        }

        emit Minted(msg.sender, startId, qty, cost, thirdFree);
    }

    // -------------------------------------------------------------- reveal

    /// @notice Siapa pun boleh memanggil, sekali, setelah revealBlock lewat.
    function reveal(bytes32 secret_) external {
        require(seed == 0, "revealed");
        require(block.number >= revealBlock, "too early");
        require(keccak256(abi.encodePacked(secret_)) == provenanceCommit, "bad secret");
        uint256 s = uint256(keccak256(abi.encode(blockhash(revealBlock), secret_)));
        revealSecret = secret_;
        seed = s;
        emit Revealed(secret_, s);
    }

    // --------------------------------------------------------------- views

    function tierOf(uint256 tokenId) public view returns (string memory) {
        uint256 t = _traitHash(tokenId) % 10000;
        if (t < 5500) return "Common";
        if (t < 8000) return "Uncommon";
        if (t < 9300) return "Rare";
        if (t < 9800) return "Epic";
        if (t < 9950) return "Legendary";
        return "Mythic";
    }

    function _traitHash(uint256 tokenId) internal view returns (uint256) {
        return uint256(keccak256(abi.encodePacked(seed, tokenId)));
    }

    function tokenURI(uint256 tokenId) public view override returns (string memory) {
        _requireOwned(tokenId);
        if (seed == 0) return _unrevealedURI(tokenId);

        uint256 h = _traitHash(tokenId);
        string memory tier = tierOf(tokenId);
        (string memory body, string memory eyes, string memory acc, string memory aura) = _traits(h);
        string memory svg = _svg(tokenId, h, tier, body, eyes, acc, aura);

        string memory json = string.concat(
            '{"name":"Pengupunk #', tokenId.toString(),
            '","description":"Agent-gated collectible on BNB Chain. No owner, no withdraw. Rarity and order sealed by block hash.",',
            '"attributes":[{"trait_type":"Tier","value":"', tier, '"},'
            '{"trait_type":"Body","value":"', body, '"},'
            '{"trait_type":"Eyes","value":"', eyes, '"},'
            '{"trait_type":"Accessory","value":"', acc, '"},'
            '{"trait_type":"Aura","value":"', aura, '"}],'
            '"image":"data:image/svg+xml;base64,', Base64.encode(bytes(svg)), '"}'
        );
        return string.concat("data:application/json;base64,", Base64.encode(bytes(json)));
    }

    function _unrevealedURI(uint256 tokenId) internal pure returns (string memory) {
        string memory svg = string.concat(
            '<svg xmlns="http://www.w3.org/2000/svg" width="400" height="400" viewBox="0 0 400 400">',
            '<rect width="400" height="400" fill="#0a0c10"/>',
            '<rect x="60" y="60" width="280" height="280" rx="24" fill="#11141b" stroke="#2a2f3a" stroke-width="2"/>',
            '<text x="200" y="200" font-family="monospace" font-size="26" fill="#6b7280" text-anchor="middle">SEALED</text>',
            '<text x="200" y="240" font-family="monospace" font-size="16" fill="#4b5563" text-anchor="middle">#', tokenId.toString(), '</text>',
            '</svg>'
        );
        return string.concat(
            "data:application/json;base64,",
            Base64.encode(
                bytes(
                    string.concat(
                        '{"name":"Pengupunk #',
                        tokenId.toString(),
                        ' (sealed)","image":"data:image/svg+xml;base64,',
                        Base64.encode(bytes(svg)),
                        '"}'
                    )
                )
            )
        );
    }

    function _traits(uint256 h) internal pure returns (string memory, string memory, string memory, string memory) {
        string[5] memory bodies = ["Slate", "Frost", "Ember", "Moss", "Ink"];
        string[5] memory eyesSet = ["Dot", "Visor", "Spark", "Void", "Ring"];
        string[6] memory accs = ["None", "Scarf", "Antenna", "Chain", "Horns", "Crown"];
        string[4] memory auras = ["None", "Faint", "Pulse", "Halo"];
        return (
            bodies[(h >> 8) % 5],
            eyesSet[(h >> 16) % 5],
            accs[(h >> 24) % 6],
            auras[(h >> 32) % 4]
        );
    }

    function _svg(
        uint256 tokenId,
        uint256 h,
        string memory tier,
        string memory body,
        string memory eyes,
        string memory acc,
        string memory aura
    ) internal pure returns (string memory) {
        string[6] memory fills = ["#5b6472", "#8fb8d8", "#c96a4a", "#6f8f5a", "#2b2f38", "#000000"];
        string memory fill = fills[(h >> 8) % 5];
        string memory glow = _tierGlow(tier);

        string memory head = string.concat(
            '<svg xmlns="http://www.w3.org/2000/svg" width="400" height="400" viewBox="0 0 400 400">',
            '<defs><radialGradient id="g" cx="50%" cy="45%" r="60%"><stop offset="0%" stop-color="', glow, '" stop-opacity="0.35"/><stop offset="100%" stop-color="#0a0c10" stop-opacity="0"/></radialGradient></defs>',
            '<rect width="400" height="400" fill="#0a0c10"/><rect width="400" height="400" fill="url(#g)"/>',
            '<ellipse cx="200" cy="232" rx="104" ry="118" fill="', fill, '"/>',
            '<ellipse cx="200" cy="150" rx="86" ry="76" fill="', fill, '"/>'
        );

        string memory face = string.concat(
            _eyes((h >> 16) % 5),
            '<path d="M186 196 L214 196 L200 214 Z" fill="#f0a24a"/>',
            _accessory(acc, (h >> 24) % 6)
        );

        string memory tail = string.concat(
            '<text x="200" y="372" font-family="monospace" font-size="15" fill="', glow, '" text-anchor="middle">', tier, ' \u00b7 #', tokenId.toString(), '</text>',
            '</svg>'
        );
        return string.concat(head, face, tail);
    }

    function _eyes(uint256 v) internal pure returns (string memory) {
        if (v == 0) return '<circle cx="172" cy="150" r="9" fill="#0a0c10"/><circle cx="228" cy="150" r="9" fill="#0a0c10"/>';
        if (v == 1) return '<rect x="146" y="140" width="108" height="20" rx="10" fill="#0a0c10"/><rect x="158" y="146" width="18" height="8" rx="4" fill="#7fe3c0"/><rect x="224" y="146" width="18" height="8" rx="4" fill="#7fe3c0"/>';
        if (v == 2) return '<circle cx="172" cy="150" r="8" fill="#0a0c10"/><circle cx="228" cy="150" r="8" fill="#0a0c10"/><circle cx="172" cy="150" r="3" fill="#ffd479"/><circle cx="228" cy="150" r="3" fill="#ffd479"/>';
        if (v == 3) return '<rect x="150" y="138" width="100" height="26" rx="6" fill="#0a0c10"/>';
        return '<circle cx="172" cy="150" r="13" fill="none" stroke="#0a0c10" stroke-width="5"/><circle cx="228" cy="150" r="13" fill="none" stroke="#0a0c10" stroke-width="5"/>';
    }

    function _accessory(string memory acc, uint256 v) internal pure returns (string memory) {
        if (v == 0) return "";
        if (v == 1) return '<rect x="150" y="214" width="100" height="18" rx="9" fill="#e0574f"/>';
        if (v == 2) return '<rect x="196" y="52" width="8" height="34" fill="#9aa4b2"/><circle cx="200" cy="46" r="7" fill="#ffd479"/>';
        if (v == 3) return '<path d="M160 250 L240 250 L230 268 L170 268 Z" fill="#d4af37" opacity="0.85"/>';
        if (v == 4) return '<path d="M150 96 L168 60 L182 96 Z" fill="#e8e2d5"/><path d="M250 96 L232 60 L218 96 Z" fill="#e8e2d5"/>';
        return '<path d="M154 96 L172 66 L200 84 L228 66 L246 96 Z" fill="#d4af37"/>';
    }

    function _tierGlow(string memory tier) internal pure returns (string memory) {
        bytes32 t = keccak256(bytes(tier));
        if (t == keccak256(bytes("Common"))) return "#7a828f";
        if (t == keccak256(bytes("Uncommon"))) return "#7fe3c0";
        if (t == keccak256(bytes("Rare"))) return "#6fa8ff";
        if (t == keccak256(bytes("Epic"))) return "#b98cff";
        if (t == keccak256(bytes("Legendary"))) return "#ffb347";
        return "#ff5f6d";
    }

    // ------------------------------------------------------------- plumbing

    function supportsInterface(bytes4 interfaceId) public view override(ERC721, ERC2981) returns (bool) {
        return super.supportsInterface(interfaceId);
    }
}
